use mtime_antikythera::SAROS;use mtime_core::{CoordinateTime,Provenance,QualityClass,Tt};use mtime_cosmology::{infer_age,planck_2018_flat_reference};use mtime_hijri::{CalendarProfile,HijriAstronomicalState};use mtime_timescales::tt_to_tcg;
fn main(){let tt=CoordinateTime::<Tt>::new(2_453_750.5,0.892_482_639,0.0).unwrap();let tcg=tt_to_tcg(&tt).unwrap();let state=HijriAstronomicalState{conjunction_jd_tt:None,sunset_jd_ut1:None,moon_altitude_topocentric_deg:3.1,elongation_geocentric_deg:6.5,moon_age_hours:None,moon_lag_minutes:None,site_id:"GOLDEN".into(),ephemeris_source:"golden".into(),quality:QualityClass::Reference};let mabims=CalendarProfile::mabims_indonesia_2026().evaluate(&state).met.unwrap();let age=infer_age(planck_2018_flat_reference(),1e-10,Provenance::new("golden")).unwrap();println!("tt_to_tcg_d2={:.16}",tcg.jd_parts().d2);println!("saros_jd={:.10}",SAROS.recurrence_jd(2_460_409.263,1));println!("mabims_pass={}",mabims);println!("planck_age_gyr={:.9}",age.gyr);}
